using namespace watchlistWorkspace;
WatchlistReconciliationPage::WatchlistReconciliationPage(std::shared_ptr<WatchlistReconciliationStore>s,Reader r,Confirmer c,QWidget*p,bool initialRead):QWidget(p),store(std::move(s)),read(std::move(r)),confirm(std::move(c)){
 setObjectName("watchlistReconciliationPage");auto*l=new QVBoxLayout(this);l->setContentsMargins(8,8,8,8);auto*intro=new QLabel("自选关联检查 · 历史配置保留");intro->setWordWrap(true);l->addWidget(intro);auto*bar=new QHBoxLayout;l->addLayout(bar);auto button=[this,bar](QString title,QString tag,std::function<void()>f){auto*b=new QPushButton(title);b->setObjectName(tag);bar->addWidget(b);connect(b,&QPushButton::clicked,this,[this,f]{attempt(f);});};button("重读","reconciliationReload",[this]{reload();});button("预览协调","reconciliationPreview",[this]{previewChanges();});button("明确确认协调","reconciliationConfirm",[this]{confirmChanges();});button("取消","reconciliationCancel",[this]{cancelChanges();});
 ack=new QCheckBox("我已核对，接受将移除关联及协调前完整配置移入历史保留");ack->setObjectName("reconciliationAck");l->addWidget(ack);status=new QLabel;status->setObjectName("reconciliationStatus");status->setWordWrap(true);l->addWidget(status);
 auto*split=new QSplitter;split->setObjectName("reconciliationViewport");history=new QListWidget;history->setObjectName("reconciliationHistory");reader=new QPlainTextEdit;reader->setObjectName("reconciliationReader");reader->setReadOnly(true);split->addWidget(history);split->addWidget(reader);split->setSizes({200,700});l->addWidget(split,1);auto*pages=new QHBoxLayout;l->addLayout(pages);for(int d:{-1,1}){auto*b=new QPushButton(d<0?"上一段":"下一段");b->setObjectName(d<0?"reconciliationPrevious":"reconciliationNext");pages->addWidget(b);connect(b,&QPushButton::clicked,this,[this,d]{if(d<0)readOffset=std::max(0,readOffset-24000);else if(readOffset+24000<readText.size())readOffset+=24000;paintReader();});}
 connect(history,&QListWidget::itemClicked,this,[this](QListWidgetItem*i){attempt([this,i]{openHistory(i->data(Qt::UserRole).toString());});});setDarkTheme(false);if(initialRead)attempt([this]{reload();});
}
void WatchlistReconciliationPage::cancelRead(){if(snapshotReader)snapshotReader->cancel();restoringRead=false;setProperty("snapshotLoading",false);}
void WatchlistReconciliationPage::ensureSnapshotReader(){
 if(!snapshotReader)snapshotReader=new PageSnapshotReader(this,{},[this](QJsonObject result,QString error){
  setProperty("snapshotLoading",false);if(!error.isEmpty()){status->setText("配置暂不可读，原预览和历史保留："+error);return;}
  if(result.value("restoredView").toBool()){restoringRead=false;readText=result.value("text").toString();paintReader();paintHistory(result.value("history").toArray());status->setText("协调页面已恢复；需重新核对勾选，提交仍复核配置和当前身份。");return;}
  applyCurrent(result["current"].toObject(),result["history"].toArray(),result["text"].toString());
 });
}
void WatchlistReconciliationPage::setAsyncReader(std::function<Reader()> factory){asyncFactory=std::move(factory);ensureSnapshotReader();reload();}
void WatchlistReconciliationPage::restoreRead(){
 ensureSnapshotReader();auto saved=saveState();auto owned=store;restoringRead=true;setProperty("snapshotLoading",true);
 snapshotReader->request([owned,saved]{auto pending=saved.value("packet").toObject();auto id=saved.value("historyId").toString();QString text;if(!pending.isEmpty())text=watchlistReconciliation::describe(pending)+QString::fromUtf8(QJsonDocument(pending).toJson(QJsonDocument::Indented));else if(!id.isEmpty())text="完整历史：含协调前全部配置和原成员顺序\n"+QString::fromUtf8(QJsonDocument(owned->history(id)).toJson(QJsonDocument::Indented));return QJsonObject{{"restoredView",true},{"history",owned->historyList()},{"text",text}};});
}
void WatchlistReconciliationPage::showEvent(QShowEvent* event){QWidget::showEvent(event);if(!snapshotReader||!property("snapshotLoading").toBool())return;bool restore=restoringRead;cancelRead();attempt([this,restore]{if(restore)restoreRead();else reload();});}
void WatchlistReconciliationPage::applyCurrent(QJsonObject result,QJsonArray rows,QString text){packet={};uncertain=false;historyId.clear();ack->setChecked(false);readOffset=0;readText=std::move(text);paintReader();paintHistory(rows);status->setText(result.value("state")=="ready"?"当前范围已协调；重读未写配置。":"当前范围待协调；原关系完整保留，请先预览。");}
void WatchlistReconciliationPage::attempt(std::function<void()>f){try{f();}catch(const std::exception&e){status->setText((uncertain?QString("协调结果未确认，保留预览；请明确重读当前配置与历史，勿重试。 "):QString{})+QString::fromUtf8(e.what()));}}
void WatchlistReconciliationPage::paintReader(){int start=std::min(readOffset,int(readText.size())),end=std::min(start+24000,int(readText.size()));if(start>0&&start<readText.size()&&readText[start].isLowSurrogate())start--;if(end<readText.size()&&end>0&&readText[end-1].isHighSurrogate())end--;reader->setPlainText(QString("完整内容 %1–%2 / %3\n").arg(start).arg(end).arg(readText.size())+readText.mid(start,end-start));}
void WatchlistReconciliationPage::listHistory(){paintHistory(store->historyList());}
void WatchlistReconciliationPage::paintHistory(QJsonArray rows){history->clear();for(auto v:rows){auto r=v.toObject();auto*i=new QListWidgetItem(r.value("confirmedAt").toString()+" · "+r.value("beforeRevision").toString()+" → "+r.value("afterRevision").toString(),history);i->setData(Qt::UserRole,r.value("id").toString());}}
void WatchlistReconciliationPage::reload(){need(bool(store)&&bool(read),"未接当前本机配置与完整主自选输入");if(snapshotReader&&asyncFactory){auto next=asyncFactory();restoringRead=false;setProperty("snapshotLoading",true);snapshotReader->request(std::move(next));return;}cancelRead();auto result=store->current(read());applyCurrent(result,store->historyList(),QString::fromUtf8(QJsonDocument(result).toJson(QJsonDocument::Indented)));}
void WatchlistReconciliationPage::previewChanges(){cancelRead();need(!uncertain&&bool(store)&&bool(read),"需先明确重读未确认结果");packet=store->preview(read());historyId.clear();ack->setChecked(false);readOffset=0;readText=watchlistReconciliation::describe(packet)+QString::fromUtf8(QJsonDocument(packet).toJson(QJsonDocument::Indented));paintReader();status->setText("仅预览；核对每个组完整旧关系及移入历史的成员，再明确确认。");}
void WatchlistReconciliationPage::confirmChanges(){cancelRead();need(!uncertain&&!packet.isEmpty()&&ack->isChecked()&&bool(read),"先预览并明确接受完整旧配置入历史");need(equal(store->preview(read()),packet),"确认前配置或当前证券已变，请重新预览");if(packet.value("noChange").toBool()){cancelChanges();status->setText("没有范围变化；未调用确认或迁移。");return;}need(bool(confirm),"宿主未接主线程 / 协调锁下的确认回调");uncertain=true;auto result=confirm(packet,true);need(result.value("schema")=="watchlist-reconciliation-result/v1"&&result.value("state")=="committed"&&result.value("previewHash")==packet.value("summaryHash"),"协调回执未确认请求摘要");auto record=store->history(text(result,"historyId"));need(equal(record.value("preview"),packet)&&equal(record.value("afterConfig"),result.value("config")),"协调回执与完整历史不一致");auto s=validate(result.value("snapshot").toObject());need(equal(watchlistWorkspacePersistence::config(s),record.value("afterConfig"))&&equal(watchlistReconciliation::scope({{"mainIds",s.value("mainIds")},{"instruments",s.value("instruments")}}),record.value("rosterScope")),"协调回执主自选身份未确认");uncertain=false;packet={};ack->setChecked(false);openHistory(result.value("historyId").toString());listHistory();status->setText("本地关联协调已保存，协调前完整配置和旧关系已入历史；主自选及行情未写。");}
void WatchlistReconciliationPage::cancelChanges(){cancelRead();need(!uncertain,"保存结果未确认，请明确重读当前配置与历史");packet={};ack->setChecked(false);historyId.clear();readText.clear();readOffset=0;paintReader();status->setText("已取消预览；未调用确认、未迁移、未写配置。");}
void WatchlistReconciliationPage::openHistory(QString id){cancelRead();need(!uncertain,"先重读未确认结果");auto r=store->history(id);packet={};ack->setChecked(false);historyId=id;readOffset=0;readText="完整历史：含协调前全部配置和原成员顺序\n"+QString::fromUtf8(QJsonDocument(r).toJson(QJsonDocument::Indented));paintReader();}
QJsonObject WatchlistReconciliationPage::saveState()const{return {{"schema","watchlist-reconciliation-view/v1"},{"packet",packet},{"uncertain",uncertain},{"historyId",historyId},{"readOffset",readOffset}};}
void WatchlistReconciliationPage::restoreState(QJsonObject s){cancelRead();need(text(s,"schema")=="watchlist-reconciliation-view/v1"&&s.value("packet").isObject()&&s.value("uncertain").isBool()&&s.value("readOffset").isDouble(),"协调页面状态损坏");auto pending=s.value("packet").toObject();if(!pending.isEmpty())need(pending.value("schema")=="watchlist-reconciliation-preview/v1","协调预览状态格式无效");packet=pending;uncertain=s.value("uncertain").toBool();ack->setChecked(false);historyId=text(s,"historyId");readOffset=std::max(0,s.value("readOffset").toInt());readText.clear();paintReader();status->setText("正在后台恢复协调页面；原预览和位置保留。");restoreRead();}
bool WatchlistReconciliationPage::back(){if(uncertain||!packet.isEmpty()){status->setText("存在待确认预览或未确认结果，请明确取消 / 重读后离开。");return true;}if(!historyId.isEmpty()){cancelRead();historyId.clear();readText.clear();readOffset=0;paintReader();return true;}return false;}
void WatchlistReconciliationPage::setDarkTheme(bool dark){setStyleSheet(QString("QWidget{background:%1;color:%2;} QPlainTextEdit,QListWidget{background:%3;} QPushButton{padding:5px;min-height:24px;}").arg(dark?"#111a26":"#ffffff",dark?"#dce5f0":"#243449",dark?"#172232":"#f4f7fb"));}
